const crypto = require('crypto');
const asObj = (v) => (v && typeof v === 'object' && !Array.isArray(v) ? v : {});
let body = asObj($json.body);
if (!Object.keys(body).length && typeof $json.body === 'string') {
  try { body = asObj(JSON.parse($json.body)); } catch {}
}
if (!Object.keys(body).length) body = asObj($json);

const toBool = (v) => v === true || String(v || '').toLowerCase() === 'true' || String(v || '') === '1';
const jobId = String(body.job_id || body.jobId || '').trim();
if (!jobId) {
  return [{ json: { route: 'error', statusCode: 400, error_code: 'JOB_ID_REQUIRED', message: 'job_id is required' } }];
}

const base = String($env.GOV_CLIENT_GOVHUB_BASE_URL || 'https://govhub.proforma.net.br').replace(/\/+$/,'');
const partnerId = String($env.GOV_CLIENT_PARTNER_ID || 'proforma-partner-test-001').trim();
const secret = String($env.GOV_CLIENT_HMAC_SECRET || '').trim();
if (!secret) {
  return [{ json: { route: 'error', statusCode: 500, error_code: 'CLIENT_SECRET_MISSING', message: 'GOV_CLIENT_HMAC_SECRET not configured' } }];
}

const idempotencyKey = String(body.idempotency_key || body.idempotencyKey || `IDEMP-${jobId}`).trim();
const correlationId = String(body.correlation_id || body.correlationId || `CORR-${jobId}`).trim();

const payload = asObj(body.payload);
const requestBody = { job_id: jobId, payload: Object.keys(payload).length ? payload : body };
const bodyRaw = JSON.stringify(requestBody);
const ts = String(Math.floor(Date.now() / 1000));
const nonce = String(body.nonce || crypto.randomUUID());
let signature = crypto.createHmac('sha256', secret).update(`${ts}.${nonce}.${bodyRaw}`).digest('hex');
if (toBool(body.simulate_bad_signature)) signature = 'deadbeef';

const timeoutMs = toBool(body.simulate_timeout) ? 1 : Number(body.timeout_ms || 10000);

return [{
  json: {
    route: 'valid',
    job_id: jobId,
    partner_id: partnerId,
    correlation_id: correlationId,
    idempotency_key: idempotencyKey,
    govhub_output_url: `${base}/webhook/govhub-output`,
    govhub_status_url: `${base}/webhook/govhub-status`,
    request_body: requestBody,
    x_timestamp: ts,
    x_nonce: nonce,
    x_signature: signature,
    timeout_ms: Number.isFinite(timeoutMs) ? Math.max(1, timeoutMs) : 10000
  }
}];

const req = $node['Validate + Sign'].json || {};
const body = ($json.body && typeof $json.body === 'object') ? $json.body : {};
const statusCode = Number($json.statusCode || $json.responseCode || 0);
const errMsg = String($json?.error?.message || $json.message || body.message || 'dispatch failed');
const dispatchOk = !$json.error && statusCode >= 200 && statusCode < 300 && body.ack === true;
if (dispatchOk) {
  return [{ json: { dispatch_ok: true, job_id: req.job_id, status_code: statusCode, partner_id: req.partner_id, idempotency_key: req.idempotency_key, correlation_id: req.correlation_id } }];
}
return [{ json: { dispatch_ok: false, job_id: req.job_id, partner_id: req.partner_id, idempotency_key: req.idempotency_key, correlation_id: req.correlation_id, govhub_status_url: req.govhub_status_url, status_code: statusCode || 502, error_code: String(body.error_code || ($json.error ? 'DISPATCH_HTTP_ERROR' : 'DISPATCH_REJECTED')), error_message: errMsg.slice(0, 250) } }];
